"""RFC-7807-style rendering for collected legacy validation failures."""

_VALID_CODES = frozenset(
    f"E{number:04d}"
    for start, end in (
        (1001, 1005),
        (2001, 2004),
        (3001, 3007),
        (4001, 4004),
        (5001, 5005),
    )
    for number in range(start, end + 1)
)


def problem_details(errors: list[dict]) -> dict:
    """Return the legacy validation result as an RFC-7807-style document."""
    for error in errors:
        if error["code"] not in _VALID_CODES:
            raise ValueError("Unknown legacy validation error code")

    blocked = any(error["severity"] == "BLOCK" for error in errors)

    return {
        "type": "https://meridian-crm.example/problems/validation",
        "title": "Legacy validation failed",
        "status": 422 if blocked else 200,
        "blocked": blocked,
        "errors": [
            {
                "code": error["code"],
                "message": error["message"],
                "severity": error["severity"],
            }
            for error in errors
        ],
    }
